import numpy as np, wave
SR = 44100
HDR = 23335          # header rate: note 60 plays authored content 1:1, note = MIDI pitch
rng = np.random.default_rng(20240719)

def write_wav(name, x, peak=0.85):
    x = np.asarray(x, dtype=float)
    p = np.abs(x).max()
    if p > 1e-9:
        x = x / p * peak
    pcm = (np.clip(x, -1, 1) * 32767).astype('<i2')
    w = wave.open('/workspace/samples/' + name + '.wav', 'wb')
    w.setnchannels(1); w.setsampwidth(2); w.setframerate(HDR)
    w.writeframes(pcm.tobytes()); w.close()
    return len(x)

def t_(secs):
    return np.arange(int(round(secs * SR))) / SR

def phase_freq(freq):
    return np.cumsum(2 * np.pi * np.asarray(freq, float) / SR)

def harm(ph, f0eff, nh, kind='saw', duty=0.5):
    """band-limited additive oscillator. f0eff = instantaneous base freq array (for limiting)"""
    y = np.zeros(len(ph))
    if kind == 'saw':
        for k in range(1, nh + 1):
            ok = f0eff * k < 0.46 * SR
            y += (ok / k) * np.sin(k * ph)
        y *= 2 / np.pi
    elif kind == 'square':
        for k in range(1, nh + 1):
            if k % 2 == 0: continue
            ok = f0eff * k < 0.46 * SR
            y += (ok / k) * np.sin(k * ph)
        y *= 4 / np.pi
    elif kind == 'pulse':
        for k in range(1, nh + 1):
            ok = f0eff * k < 0.46 * SR
            y += (ok / k) * np.sin(k * ph) * (1 + 2 * np.cos(2 * np.pi * k * duty))
        y *= 2 / np.pi
    return y

def env_exp(n, a, tau, floor=0.0, hold=0.0):
    t = np.arange(n) / SR
    e = np.ones(n)
    if a > 0:
        na = max(1, int(a * SR))
        e[:na] = np.linspace(0, 1, na) ** 1.5
        e[na:] = np.exp(-(t[na:] - na / SR) / tau) if tau > 0 else 0
    else:
        e = np.exp(-t / tau) if tau > 0 else np.ones(n)
    if floor > 0: e = np.maximum(e, floor)
    return e

