    n = int(ms / 1000 * SR); n = min(n, len(x))
    x = x.copy()
    if n > 1: x[-n:] *= np.linspace(1, 0, n)
    head = min(n, len(x) // 4)
    if head > 1: x[:head] *= np.linspace(0, 1, head)
    return x

def onepole(x, fc):
    fc = np.clip(np.asarray(fc, float), 20, 0.45 * SR)
    a = np.exp(-2 * np.pi * fc / SR)
    out = np.empty(len(x)); acc = 0.0
    xi = np.asarray(x, float)
    for i in range(len(x)):
        acc = a[i] * acc + (1 - a[i]) * xi[i]
        out[i] = acc
    return out

def svf(x, fc, res=1.0, ftype='lp'):
    """state variable filter, fc array or scalar (Hz), res 0.5..8"""
    x = np.asarray(x, float)
    n = len(x)
    fc = np.full(n, fc, float) if np.isscalar(fc) else np.clip(np.asarray(fc, float), 20, 0.45 * SR)
    k = 2 * np.sin(np.pi * fc / SR)
