        elif ftype == 'bp': out[i] = pb
        else: out[i] = hpv
        lp[i] = pl; bp[i] = pb
    return out

def highpass(x, fc, order=2):
    y = x
    for _ in range(order):
        a = np.exp(-2 * np.pi * np.clip(fc, 20, 0.45 * SR) / SR)
        s = np.zeros_like(y); prev = 0.0
        acc = 0.0
        out = np.empty(len(y))
        for i in range(len(y)):
            acc = a * acc + (1 - a) * y[i]
            out[i] = y[i] - acc
            prev = y[i]
        y = out
    return y

def bandpass(x, f1, f2, q=2.0):
    return svf(svf(x, f1, q, 'hp'), f2, q, 'lp')

def nz(n):
    return rng.standard_normal(n)
